  const mvpPanel=prediction?`<aside class="prediction-mvp"><p class="eyebrow">Candidato MVP</p><strong>${esc(prediction.mvpCandidate.name)}</strong><span>${esc(teams.find(item=>item.id===prediction.mvpCandidate.teamId)?.name||prediction.mvpCandidate.teamId)} · ${esc(prediction.mvpCandidate.role)}</span><ul>${prediction.mvpCandidate.evidence.map(item=>`<li>${esc(item)}</li>`).join("")}</ul><small>Confidenza ${esc(prediction.mvpCandidate.confidence)} · valutazione preliminare</small></aside>`:"";
  const extendedPanel=prediction?`<section class="section reading-projection-prototype prediction-volume-section"><header class="section-heading"><div><p class="eyebrow">Proiezione per squadra</p><h2>Gol, tiri, specchio, corner, falli e cartellini</h2></div><p>Valore centrale con intervallo prudenziale.</p></header><div class="prediction-volume-grid">${prediction.teamProjections.map(projectionCard).join("")}</div><p class="objective-method">I cartellini hanno intervallo più ampio perché l'arbitro non è ancora designato. Dove la base storica non è disponibile il valore resta N/D.</p><div class="prediction-players-grid">${bookedPanel}${mvpPanel}</div></section>`:`<section class="section reading-projection-prototype"><h2>Proiezioni in preparazione</h2></section>`;
